-- Import sedute 14–28/09/2026 + esercizi mancanti (idempotente)
on conflict (id) do nothing;
on conflict (id) do nothing;
select (select count(*) from public.exercises) as esercizi, (select count(*) from public.sessions where data->>'stato'='svolta' and data->>'data' between '2026-09-14' and '2026-09-28') as sedute_settembre;
