('5eed0000-0000-4000-8000-000000000135', '{"code":"TEC-19","title":"Ricezione-trasmissione su rombo 4+4 (lungo, scarico, orientato)","area":"tecnica","fase":["attivazione","centrale"],"obiettivi":["ricezione","controllo orientato","passaggio","uno-due"],"eta":"U9-U12","giocatori":"4 blu + 4 rossi su 2 file","spazio":"File a 12–15 m, coni laterali a ~6–7 m dal centro","durata":10,"materiale":"4 coni (2 con paletto), 2 palloni","perche":"I 3 gesti del giorno: trasmissione lunga, ricezione in anticipo, controllo orientato; postura aperta per ricevere già girati. Tanti tocchi per tutti.","descrizione":"Blu 1 passa lungo a Rosso 3 e resta. Rosso 3 va incontro (anticipo) e conduce fino a metà corsia, scarica su Blu 1 e si apre verso il cono alla sua destra. Blu 1 ripassa: Rosso 3 fa controllo orientato verso la sua fila e passa a Rosso 2, poi va in coda. Blu 1 torna in coda; il ciclo riparte a lati invertiti.","varianti":"Apertura a sinistra (piede debole). Tutto a 2 tocchi max. 2° pallone quando il ritmo è buono.","coaching":"Ricezione in anticipo: vai verso il pallone. Controllo orientato col piede lontano, corpo aperto verso la fila. Passaggio lungo: appoggio accanto alla palla, palla a terra. Scarico di prima quando possibile.","fonte":"Raccolta sedute 14–28/09/2026 (DT)","diagram":{"field":{"preset":"spazio","w":16,"h":16},"steps":[{"title":"Passaggio lungo","note":""},{"title":"Anticipo e conduzione","note":""},{"title":"Scarico e apertura","note":""},{"title":"Controllo orientato","note":"Passa al 2 della fila"},{"title":"Fine"}],"items":[{"id":"it911","type":"cone","pos":{"0":{"x":8,"y":1.5}}},{"id":"it912","type":"cone","pos":{"0":{"x":8,"y":14.5}}},{"id":"it913","type":"pole","pos":{"0":{"x":2,"y":8}}},{"id":"it914","type":"pole","pos":{"0":{"x":14,"y":8}}},{"id":"it915","type":"playerA","label":"1","pos":{"0":{"x":8,"y":15.5},"1":{"x":8,"y":12}}},{"id":"it916","type":"playerB","label":"3","pos":{"0":{"x":8,"y":0.5},"1":{"x":8,"y":4},"2":{"x":8,"y":7.5},"3":{"x":11.5,"y":9}}},{"id":"it917","type":"playerB","label":"2","pos":{"0":{"x":9.2,"y":-0.3}}},{"id":"it918","type":"ball","pos":{"0":{"x":8.6,"y":15.2},"1":{"x":8.4,"y":4.3},"2":{"x":8.4,"y":7.9},"3":{"x":8.4,"y":12.4},"4":{"x":12,"y":9.4},"5":{"x":9.4,"y":0.2}}}],"arrows":[{"id":"ar919","kind":"pass","step":0,"from":{"x":8.6,"y":15.2},"to":{"x":8.4,"y":4.3}},{"id":"ar920","kind":"run","step":0,"from":{"x":8,"y":0.5},"to":{"x":8,"y":4}},{"id":"ar921","kind":"dribble","step":1,"from":{"x":8,"y":4},"to":{"x":8,"y":7.5}},{"id":"ar922","kind":"pass","step":2,"from":{"x":8.4,"y":7.9},"to":{"x":8.4,"y":12.4},"curve":1},{"id":"ar923","kind":"run","step":2,"from":{"x":8,"y":7.5},"to":{"x":11.5,"y":9}},{"id":"ar924","kind":"pass","step":3,"from":{"x":8.4,"y":12.4},"to":{"x":12,"y":9.4}},{"id":"ar925","kind":"pass","step":4,"from":{"x":12,"y":9.4},"to":{"x":9.4,"y":0.2}}]},"id":"5eed0000-0000-4000-8000-000000000135","updatedAt":"2026-10-01T00:00:00.000Z"}'::jsonb, now()),
('5eed0000-0000-4000-8000-000000000136', '{"code":"TAT-07","title":"Costruzione calcio a 7 + recupero e finalizzazione","area":"tattica","fase":["centrale"],"obiettivi":["smarcamento","3° uomo","transizione","tiro"],"eta":"U10-U12","giocatori":"5 blu vs 3 rossi + 2 sponde rosse + portiere","spazio":"Da 5 m oltre metà campo a linea di fondo, larghezza campo a 7; Z1/Z2 separate da 4 dischi","durata":12,"materiale":"Porta regolamentare, 4 dischi, 2 coni laterali, casacche","perche":"Dalla costruzione alla ricerca del vertice (attaccanti in Z1) con inserimento; i rossi allenano riconquista e attacco rapido con le sponde.","descrizione":"Riparte sempre dal mister: palla a Blu 1 che viene incontro. Z2: Blu 1-2-3 vs Rosso 2-3; Z1: Blu 4-5 vs Rosso 1 + P. I blu di Z2 entrano in Z1 solo quando la palla arriva a un attaccante in Z1. Tiro da Z2 solo dopo scambio con l’attaccante. Se i rossi recuperano attaccano la stessa porta usando le 2 sponde, 5″ per concludere. A 6′ blu e rossi invertono; sponde ogni 3′.","varianti":"1 rosso in più in Z1 se i blu segnano troppo. Gol doppio se segna un giocatore arrivato da Z2.","coaching":"Blu 1 riceve già orientato in avanti. Attaccanti Z1: smarcati incontro o in profondità. Da Z2 inserimento immediato appena la palla entra in Z1. Rossi: dopo il recupero guardare sponda e porta.","fonte":"Raccolta sedute 14–28/09/2026 (DT)","diagram":{"field":{"preset":"metacampo","w":30,"h":30},"steps":[{"title":"Palla dal mister a Blu 1","note":""},{"title":"Verticale in Z1","note":""},{"title":"Inserimento e conclusione","note":""},{"title":"Fine"}],"items":[{"id":"it926","type":"gk","pos":{"0":{"x":29,"y":15}}},{"id":"it927","type":"disc","pos":{"0":{"x":17,"y":3}}},{"id":"it928","type":"disc","pos":{"0":{"x":17,"y":11}}},{"id":"it929","type":"disc","pos":{"0":{"x":17,"y":19}}},{"id":"it930","type":"disc","pos":{"0":{"x":17,"y":27}}},{"id":"it931","type":"jolly","label":"S","pos":{"0":{"x":30.4,"y":6}}},{"id":"it932","type":"jolly","label":"S","pos":{